"""Offline HTML hierarchy and patch review generated by code at each graph stage."""
import json
import os
from pathlib import Path

from ..storage.io import atomic_bytes




def compact_data(store, stage, data):
    effective = data.get('analysis', data)
    graph = effective.get('story_graph', {})
    from .name_normalization import apply
    normalized = store.read('normalize')
    if effective.get('name_normalization'):
        normalized = apply(normalized, effective['name_normalization'])
    rows = {r['id']: r for r in normalized.get('utterances', [])}
    decisions = {r['utterance_id']: r for r in effective.get('utterances', [])}
    fields = ('content_type', 'speech_style', 'speaker_kind', 'speaker_person_id',
              'addressee_type', 'addressee_person_ids', 'confidence', 'mentions',
              'evidence', 'speaker_anchor', 'bubble_tail', 'semantic_resolution', 'semantic_needs_review', 'semantic_errors')
    changes = {p.get('utterance_id'): p for p in data.get('accepted', [])}
    scenes = []
    directory = store.artifact_path(stage).parent
    for scene in graph.get('scenes', []):
        item = {k: scene.get(k) for k in ('scene_id', 'title', 'description', 'description_confidence', 'hypotheses', 'resolution')}
        item['events'] = []
        for event in scene.get('events', []):
            entry = {k: event.get(k) for k in ('event_id', 'title', 'description', 'description_confidence', 'status', 'error')}
            entry['rows'] = []
            for uid in event.get('target_ids', []):
                decision = decisions.get(uid, {})
                row = {'id': uid, 'text': rows.get(uid, {}).get('text', ''),
                       'page': rows.get(uid, {}).get('page'), 'panel_index': rows.get(uid, {}).get('panel_index'),
                       'semantic': {k: decision[k] for k in fields if k in decision}}
                patch = changes.get(uid)
                if patch:
                    before, after = patch.get('before', {}), patch.get('after', {})
                    row['change'] = {'reason': patch.get('reason'), 'fields': {
                        k: {'before': before.get(k), 'after': after.get(k)}
                        for k in sorted(set(before) | set(after)) if before.get(k) != after.get(k)}}
                entry['rows'].append(row)
            entry['pictures'] = [{'file': Path(os.path.relpath(store.directory / p['file'], directory)).as_posix(),
                                  'label': p.get('page_id', '')} for p in event.get('image_packets', [])]
            entry['attention'] = bool(entry.get('error') or event.get('status') in {'failed', 'incomplete'} or
                any(r['semantic'].get('semantic_needs_review') or r['semantic'].get('semantic_resolution') == 'unresolved'
                    or (r['semantic'].get('speaker_anchor', {}).get('person_id') is not None
                        and r['semantic']['speaker_anchor']['person_id'] != r['semantic'].get('speaker_person_id'))
                    for r in entry['rows']))
            item['events'].append(entry)
        scenes.append(item)
    stage_links = {}
    for name in ('graph', 'analyze', 'reanalyze'):
        try:
            target = store.artifact_path(name)
            if target.is_file():
                stage_links[name] = Path(os.path.relpath(target.parent / 'review.html', directory)).as_posix()
        except (KeyError, ValueError):
            continue
    return {'stage': stage, 'status': data.get('status', data.get('review_status', 'completed')),
            'chapter': graph.get('chapter', {}), 'stage_links': stage_links, 'export_path': 'result.json',
            'fallback': data.get('fallback_to_analyze', False), 'error': data.get('error'), 'scenes': scenes,
            'characters': graph.get('characters', {}), 'groups': effective.get('name_normalization', {}).get('groups', []),
            'rejected': data.get('rejected', []), 'accepted_count': len(data.get('accepted', [])),
            'issues': {**{k: effective[k] for k in ('event_failures', 'semantic_validation_issues', 'failures',
                'needs_review', 'unresolved_targets') if effective.get(k)},
                **({'batch_failures': data['batch_failures']} if data.get('batch_failures') else {})}}


def write_html(store, stage, data):
    payload = compact_data(store, stage, data)
    template = (Path(__file__).parents[1] / 'review' / 'story_graph.html').read_text(encoding='utf-8')
    serialized = json.dumps(payload, ensure_ascii=False, separators=(',', ':'), sort_keys=True)
    path = store.artifact_path(stage).parent / 'review.html'
    atomic_bytes(path, template.replace('__GRAPH_DATA__', serialized.replace('<', '\\u003c')).encode('utf-8'))
    return path


def compact_markdown(stage, data):
    effective = data.get('analysis', data)
    scenes = effective.get('story_graph', {}).get('scenes', [])
    events = [e for s in scenes for e in s.get('events', [])]
    lines = [f'# {stage} review', '', f"Status: {data.get('status', data.get('review_status', 'completed'))}", '',
             '[Interactive review: scene → event → details](review.html) · [Full artifact](result.json)', '',
             f"{len(scenes)} scenes · {len(events)} events · {sum(len(e.get('target_ids', [])) for e in events)} utterances", '']
    if data.get('fallback_to_analyze'):
        lines += ['**Reanalyze incomplete: using analyze unchanged.**', '']
    if data.get('error'):
        lines += [f"**Error:** {data['error']}", '']
    for key in ('event_failures', 'semantic_validation_issues', 'failures', 'needs_review', 'unresolved_targets'):
        if effective.get(key):
            lines.append(f"- {key}: {len(effective[key])} (see Needs review in HTML)")
    if stage == 'reanalyze':
        lines.append(f"- Applied changes: {len(data.get('accepted', []))}; proposals not applied: {len(data.get('rejected', []))}.")
        for failure in data.get('batch_failures', []):
            lines.append('- Review half failed: '+str(failure))
    lines += ['', '| Scene | Events | Utterances |', '|---|---:|---:|']
    for s in scenes:
        title = str(s.get('title', '')).replace('|', '\\|').replace('\n', ' ')
        lines.append(f"| {s['scene_id']} · {title} | {len(s.get('events', []))} | {sum(len(e.get('target_ids', [])) for e in s.get('events', []))} |")
    return '\n'.join(lines) + '\n'
